    {
      "name": "Polynomial.degreeLTEquiv",
      "module_name": "Mathlib.RingTheory.Polynomial.Basic",
      "kind": "definition",
      "type": "(R : Type u_2) → [inst : Semiring R] → (n : ℕ) → ↥(Polynomial.degreeLT R n) ≃ₗ[R] Fin n → R"
    },
    {
      "name": "Polynomial.mapAlgEquiv_toAlgHom",
      "module_name": "Mathlib.Algebra.Polynomial.AlgebraMap",
      "kind": "theorem",
      "type": "∀ {R : Type u} {A : Type z} {B : Type u_2} [inst : CommSemiring R] [inst_1 : Semiring A] [inst_2 : Semiring B]\n  [inst_3 : Algebra R A] [inst_4 : Algebra R B] (f : A ≃ₐ[R] B), ↑(Polynomial.mapAlgEquiv f) = Polynomial.mapAlgHom ↑f"
    },
    {
      "name": "Polynomial.mapAlgEquiv",
      "module_name": "Mathlib.Algebra.Polynomial.AlgebraMap",
      "kind": "definition",
      "type": "{R : Type u} →\n  {A : Type z} →\n    {B : Type u_2} →\n      [inst : CommSemiring R] →\n        [inst_1 : Semiring A] →\n          [inst_2 : Semiring B] →\n            [inst_3 : Algebra R A] → [inst_4 : Algebra R B] → (A ≃ₐ[R] B) → Polynomial A ≃ₐ[R] Polynomial B"
    },
    {
      "name": "Polynomial.coeff_map_eq_comp",
      "module_name": "Mathlib.Algebra.Polynomial.Eval.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : Semiring R] [inst_1 : Semiring S] (p : Polynomial R) (f : R →+* S),\n  (Polynomial.map f p).coeff = ⇑f ∘ p.coeff"
    },
    {
      "name": "Polynomial.lcoeff_comp_mapAlgHom_eq",
      "module_name": "Mathlib.Algebra.Polynomial.AlgebraMap",
      "kind": "theorem",
      "type": "∀ {R : Type u} {A : Type z} {B : Type u_2} [inst : CommSemiring R] [inst_1 : Semiring A] [inst_2 : Semiring B]\n  [inst_3 : Algebra R A] [inst_4 : Algebra R B] (f : A →ₐ[R] B) (n : ℕ),\n  ↑R (Polynomial.lcoeff B n) ∘ₗ (Polynomial.mapAlgHom f).toLinearMap = f.toLinearMap ∘ₗ ↑R (Polynomial.lcoeff A n)"
    }
  ]
}
